from scipy.stats import wilcoxon, binomtest
from collections import defaultdict,Counter
opt={1:0.693739,.5:0.530736,0:0.484755}; grid=np.arange(0,100001,250)
D=defaultdict(dict)
for f in files:
 r=json.loads(f.read_text()); k=float(r['kappa']); D[k,r['kind']][int(r['seed'])]=r
print('sets',len(D))
# Independent sequential time walk, no imported benchmark code.
def trajectory(rows, optimum):
 out=np.full(len(grid),np.nan); j=0; best=-np.inf
 for i,g in enumerate(grid):
  while j<len(rows) and rows[j]['spent']<=g:
   y=rows[j]['best_validated']
   if np.isfinite(y): best=max(best,y)
   j+=1
  if j>0: out[i]=best/optimum
 return out
C={key:np.stack([trajectory(r['rows'],opt[key[0]]) for seed,r in sorted(runs.items())]) for key,runs in D.items()}
def tab(k,kind):
 a=C[k,kind]; cells=[]
 for spend in (25000,50000,100000):
  v=a[:,spend//250]*100
  cells.append((v.mean(),v.std(ddof=0)/len(v)**.5))
 for threshold in (.6,.7,.8):
  hits=a>=threshold; first=np.where(hits.any(axis=1), grid[hits.argmax(axis=1)],np.inf)
  cells.append((np.median(first),np.isfinite(first).sum(),len(first),first))
 return cells
for k in (1,.5,0):
 print('\nkappa',k)
 for kind in ('pkgfn','eifn_reuse','eifn','ei','tiered','pkgfn_free'):
  t=tab(k,kind)
  print(kind,len(C[k,kind]), ' | '.join(f'{m:.4f} ± {s:.4f}' for m,s in t[:3]), ' | ',[(f'${v[0]:,.1f}',v[1]) for v in t[3:]])

def firstcost(c,target):
 ids=np.flatnonzero(c>=target-1e-12)
 return grid[ids[0]] if len(ids) else np.inf
def ratio(base,method):
 target=np.mean(base[:,-1]); xb=firstcost(base.mean(axis=0),target); xm=firstcost(method.mean(axis=0),target)
 return (target,xb,xm,xb/xm)
rng=np.random.default_rng(0)
for kind in ('pkgfn','eifn_reuse','eifn','ei'):
 b=C[1,'tiered']; a=C[1,kind]; estimate=ratio(b,a)
 sims=np.array([ratio(b[rng.integers(len(b),size=len(b))], a[rng.integers(len(a),size=len(a))])[-1] for _ in range(2000)])
 print(kind,'target, numerator, denominator, ratio:', estimate, '90% CI',np.percentile(sims,[5,50,95]),'P>=3',np.mean(sims>=3),'finite',np.isfinite(sims).mean())
# replicate seed=0 per comparison as benchmark code does
for kind in ('pkgfn','eifn_reuse','eifn','ei'):
 rng=np.random.default_rng(0); b=C[1,'tiered']; a=C[1,kind]
 sims=np.array([ratio(b[rng.integers(len(b),size=len(b))], a[rng.integers(len(a),size=len(a))])[-1] for _ in range(2000)])
 print('independent RNG reset',kind,np.percentile(sims,[5,95]), 'nonfinite',np.sum(~np.isfinite(sims)))

# Directly test inspected analyze.curve() indexing rule against independent sequential sweeps.
def inspected_curve(rows, metric='best_validated'):
 spend=np.array([r['spent'] for r in rows]); val=np.array([r[metric] if r[metric]==r[metric] else -np.inf for r in rows]); val=np.maximum.accumulate(val)
 idx=np.searchsorted(spend,grid,side='right')-1
 return np.where(idx>=0,val[np.clip(idx,0,None)],np.nan)
err=[]; nonmonotone=[]; repeated=[]; end100=[]; rows100=[]; nan=[]; missing0=[]
for (kap,kind),runs in D.items():
 for seed,r in runs.items():
  sp=np.array([row['spent'] for row in r['rows']]); yy=inspected_curve(r['rows'])/opt[kap]; zz=trajectory(r['rows'],opt[kap]);
  if not np.allclose(yy,zz,equal_nan=True): err.append((kap,kind,seed))
  if np.any(np.diff(sp)<0): nonmonotone.append((kap,kind,seed))
  if np.any(np.diff(sp)==0): repeated.append((kap,kind,seed,sp[np.where(np.diff(sp)==0)[0]].tolist()))
  if sp[-1]==100000: end100.append((kap,kind,seed))
  if np.any(sp==100000):rows100.append((kap,kind,seed))
  if sp[0]>0:missing0.append((kap,kind,seed))
  if np.any(~np.isfinite([row['best_validated'] for row in r['rows']])):nan.append((kap,kind,seed))
print('curve disagreements',err,'nonmonotone',nonmonotone,'repeat spends',len(repeated),repeated[:5],'exact100k',len(end100),'missing init0',missing0,'nonfinite scores',nan)
print('toy: duplicate at grid and beyond: ',inspected_curve([{'spent':0,'best_validated':.1},{'spent':250,'best_validated':.15},{'spent':250,'best_validated':.2},{'spent':100000,'best_validated':.3}])[[0,1,-2,-1]])
# Paired inference seeds by identity; compare zero methods. 
for baseline in ('tiered','eifn_reuse','eifn','ei'):
 d=np.array([C[1,'pkgfn'][s,-1]-C[1,baseline][s,-1] for s in range(20)])
 print('pKGFN vs',baseline,'wins/ties/losses',sum(d>0),sum(d==0),sum(d<0),'mean diff %',100*d.mean(), 'p auto',wilcoxon(d).pvalue,'p exact',wilcoxon(d,method='exact').pvalue,'p asymptotic',wilcoxon(d,method='asymptotic').pvalue,'sign one-sided',binomtest(sum(d>0),sum(d!=0),.5,alternative='greater').pvalue)
print('tiered vs pkgfn diffs',np.round((C[1,'pkgfn'][:,-1]-C[1,'tiered'][:,-1])*100,3))

# Independently implement the inspected bootstrap's sampling order (method first, baseline second),
def boot_compare(m,b,n=2000):
 rr=np.random.default_rng(0); out=[]
 for i in range(n):
  a=m[rr.integers(len(m),size=len(m))]; z=b[rr.integers(len(b),size=len(b))]; out.append(ratio(z,a)[-1])
 return np.percentile(out,[5,50,95]),np.mean(np.array(out)>=3)
for kind in ('pkgfn','eifn_reuse','eifn','ei'):
 print(kind,boot_compare(C[1,kind],C[1,'tiered']))
# Analyze only pKGFN against tiered; significance ties: count same entire trace seeds, plateau runs.
for s in range(20):
 d=C[1,'pkgfn'][s,-1]-C[1,'tiered'][s,-1]
 if d==0: print('tied seed',s,'finals',D[1,'pkgfn'][s]['rows'][-1]['best_validated'], D[1,'tiered'][s]['rows'][-1]['best_validated'])
for key in [('tiered',),('pkgfn',)]:pass
b=C[1,'tiered'].mean(0);t=b[-1]; at=np.where(b>=t-1e-12)[0]; print('tiered target',t,'first',grid[at[0]],'last prior step',grid[at[0]-1],b[at[0]-1], 'last10',b[-12:]);
# sample bootstrap plateau location
r=np.random.default_rng(0); firsts=[]; targets=[]
for i in range(2000):
 cb=C[1,'tiered'][r.integers(20,size=20)]; targets.append(cb[:,-1].mean()); firsts.append(firstcost(cb.mean(0),targets[-1]))
print('baseline first cost dist',Counter(firsts).most_common(12),'min/max',min(firsts),max(firsts))

for target in (.55,.60,.62,.625,.6270268618103603,.63,.65,.7):
 print('target',target,'tiered',firstcost(C[1,'tiered'].mean(0),target),'pkgfn',firstcost(C[1,'pkgfn'].mean(0),target),'ratio',firstcost(C[1,'tiered'].mean(0),target)/firstcost(C[1,'pkgfn'].mean(0),target))
# spending and actions k1 all policies; durations of non-improving stage actions
for kind in ('pkgfn','eifn_reuse','eifn','ei','tiered'):
 runs=D[1,kind]; acts=Counter(); counts=defaultdict(list); spends=[]; flatmax=[]; cheap_flat=[]; firstchange=[]; early=[]; repeats=[]
 for s,r in runs.items():
  acts.update(row['action'] for row in r['rows'][1:]); spends.append(r['rows'][-1]['spent']);
  for stage in ('C','A','L','T'): counts[stage].append(r['counts'][stage]-(32 if stage=='C' else 5))
  rows=r['rows']; yy=np.array([row['best_validated'] for row in rows]); changed=np.flatnonzero(np.diff(yy)>1e-14)+1
  flatmax.append(max(np.diff(np.r_[0,changed,len(rows)-1])))
  firstchange.append(rows[changed[0]]['spent'] if len(changed) else np.inf)
  if kind=='pkgfn':
   cheap_flat.append(sum(row['action']=='C' for row in rows[1:] if row['spent']<50000))
  # pathologies duplicate purchases? repeated increments of same stage counts yes action log no design; counts sum and accounting check
  cost=np.diff([row['spent'] for row in rows]); nbad=sum(not any(abs(x-y)<.0001 for y in (10,200,1500,2500,2700,4200,4210,2240)) for x in cost)
  if nbad: repeats.append((s,Counter(cost)))
 print('\n',kind,'actions',dict(acts),'new counts mean', {stage:round(np.mean(v),2) for stage,v in counts.items()},'ranges',{stage:(min(v),max(v)) for stage,v in counts.items()},'spend min/median/max',min(spends),np.median(spends),max(spends),'end<$95k',sum(np.array(spends)<95000), 'max actions between improvements',np.median(flatmax),max(flatmax),'first improvement median',np.median(firstchange),'cost anomalies',repeats[:2])
 if kind=='pkgfn':print('C under50k mean',np.mean(cheap_flat))

prices={'C':10,'A':1500,'L':2500,'T':200}
for kind in ('pkgfn','eifn_reuse','eifn','ei','tiered'):
 runs=D[1,kind]; stat={st:np.array([r['counts'][st]-(37 if st=='C' else 5) for r in runs.values()]) for st in prices};
 recon=[]; incremental=Counter(); actionchange=Counter(); conditional=Counter();
 for s,r in runs.items():
  rows=r['rows']; spent=rows[-1]['spent']; predicted=sum(prices[st]*stat[st][s] for st in prices);recon.append(spent-predicted)
  for prev,cur in zip(rows,rows[1:]):
   incremental[cur['action'],cur['spent']-prev['spent']]+=1
   actionchange[cur['action']]+=cur['best_validated']>prev['best_validated']+1e-13
 print(kind,'new stages mean', {x:np.mean(y) for x,y in stat.items()},'accounting errors',set(recon), 'action cost',dict(incremental),'improving steps',dict(actionchange))
# Last step pKGFN: what, what increase?
print('pkgfn last actions/counts',Counter((r['rows'][-1]['action'],r['rows'][-1]['spent']-r['rows'][-2]['spent']) for r in D[1,'pkgfn'].values()))
print('pKGFN final 5k increases',[(s,round((C[1,'pkgfn'][s,-1]-C[1,'pkgfn'][s,95000//250])*100,3)) for s in range(20) if C[1,'pkgfn'][s,-1]>C[1,'pkgfn'][s,95000//250]+1e-14]); print('mean change 95-100',100*(C[1,'pkgfn'][:,-1]-C[1,'pkgfn'][:,380]).mean())
# cheap / plateau: number of prints vs tests per seed, print and no improvement rate, long horizontal after last improvement
for kind in ('pkgfn','tiered','eifn'):
 runs=D[1,kind]; endings=[]; nfi=[]; blocks=[]
